class Node:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

def insert(root, key):
    if root is None:
        return Node(key)
    else:
        if key < root.val:
            root.left = insert(root.left, key)
        elif key > root.val:
            root.right = insert(root.right, key)
        else:
            return root
    return root

def search(root, key):
    if root is None:
        return False
    else:
        if key == root.val:
            return True
        elif key < root.val:
            return search(root.left, key)
        else:
